using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Reflection;
using UnityEngine;
using UnityEngine.SceneManagement;
using ChartRecorder;
public sealed class ModSmokeProbe : MonoBehaviour {
 const BindingFlags All=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;static bool created;Assembly game;GameChartMod mod;int phase,round;float began,at;bool opened,soundOffTest,smallRun;object control,info;int originalScore,hits;string root,capture;bool capturing;int[] scores=new int[3];
 public static void Initialize(){if(created)return;created=true;var go=new GameObject("FeatureProbe");DontDestroyOnLoad(go);go.AddComponent<ModSmokeProbe>();}
 void Awake(){Application.runInBackground=true;began=Time.realtimeSinceStartup;game=Assembly.Load("Assembly-CSharp");root=Path.GetDirectoryName(Application.dataPath);var cfg=MiniJSON.jsonDecode(File.ReadAllText(Path.Combine(root,"CustomCharts/smoke.json"))) as IDictionary;capture=cfg["capture"] as string;smallRun=(cfg["run"] as string)=="small";}
 void Log(string s){Debug.Log("[FEATURE-SMOKE] "+s);}void Check(bool v,string s){if(!v)throw new Exception(s);Log("PASS "+s);}void Call(object o,string m){o.GetType().GetMethod(m,All).Invoke(o,null);}void Set(object o,string p,object v){o.GetType().GetProperty(p,All).SetValue(o,v,null);}void Memory(string p,object v){game.GetType("UserMemory").GetProperty(p,All).SetValue(null,v,null);}void Next(int p){phase=p;at=Time.realtimeSinceStartup;Log("phase="+p+" round="+round);}
 void Update(){try{mod=GameChartMod.Instance;if(mod==null)return;float now=Time.realtimeSinceStartup;string scene=SceneManager.GetActiveScene().name;if(now-began>160)throw new Exception("timeout "+phase+" "+scene);if(!opened&&now-began>8){var obj=UnityEngine.Object.FindObjectOfType(game.GetType("OpeningSpectrumScript"));if(obj!=null){opened=true;Call(obj,"PlayGame");}}
 if(phase==0&&scene.Contains("SelectSong")&&now-began>12){if(smallRun&&!scene.Contains("Small")){Memory("SceneName","SmallSelectSongScene");SceneManager.LoadScene("SmallSelectSongScene");return;}Check(mod.Library.Songs.Count==2,"existing library migrates");if(smallRun)round=2;Begin();}
 if(phase==1&&now-at>2){control=UnityEngine.Object.FindObjectOfType(game.GetType("SelectSongController"));var speed=GameChartMod.Field(control,"selectSpeedScript");info=GameChartMod.Field(speed,"selectedSongInfoCore");Check(info!=null&&GameChartMod.IsCustomSlot(info),"official pre-play settings select custom slot");Check(GameChartMod.Field(speed,"selectSpeedCanvas") is Canvas,"official settings UI available");originalScore=Convert.ToInt32(GameChartMod.Property(GameChartMod.Field(info,"saveInfo"),"SyncNumber"));if(!capturing&&capture!=null){capturing=true;StartCoroutine(Capture(capture+"-settings.png"));}if(smallRun){Call(speed,"ClickSelectSceneSettingButton");Check(Convert.ToInt32(GameChartMod.Field(speed,"rectX"))==6,"official original-skin panel opens");Next(6);}else{Call(control,"StartSong");Next(2);}}
 if(phase==6&&now-at>2){var speed=GameChartMod.Field(control,"selectSpeedScript");if(capture!=null)StartCoroutine(Capture(capture+"-themes.png"));Next(7);}
 if(phase==7&&now-at>1){Call(GameChartMod.Field(control,"selectSpeedScript"),"ClickSelectSceneSettingBackButton");Call(control,"StartSong");Next(2);}
 if(phase==2&&mod.Player!=null&&Convert.ToBoolean(GameChartMod.Property(mod.Player,"FinishPrepare"))){Check(round!=1?scene=="UIB_PlayingScene":scene=="UI0B_PlayingScene","native scene choice loads "+scene);var sheet=CriAtom.GetCueSheet("ChartRecorderHits");Check(sheet!=null&&sheet.acb!=null,"original hit sound bank loaded");Check(sheet.acb.Exists("selectSong_switchSound")&&sheet.acb.Exists("selectSong_select"),"both original sound choices exist");hits=mod.HitCount;Next(3);}
 if(phase==3){if(mod.Player!=null&&Convert.ToInt32(GameChartMod.Property(mod.Player,"playStatus"))==2)Call(mod.Player,"PlayResume");if(round<2&&mod.BackgroundStarted&&mod.Player!=null)HitNotes();if(!soundOffTest&&mod.HitCount>hits&&round==0&&now-at>2){soundOffTest=true;Check(mod.HitAudio.status!=CriAtomSource.Status.Error,"CRI hit playback reports no error");mod.SetHitSound(0,.35f);int before=mod.HitCount;mod.PreviewHit();Check(mod.HitCount==before,"disabled sound produces no playback");mod.SetHitSound(1,.35f);hits=mod.HitCount;}if(scene.Contains("Settlement")){var grade=game.GetType("BMSLib.JudgeGrade");int combo=Convert.ToInt32(GameChartMod.Property(info,"MaxComboThis"));int expected=(int)(((float[])grade.GetMethod("GetUploadSyncNumber",All).Invoke(null,null))[0]*10000);int actual=Convert.ToInt32(GameChartMod.Property(info,"SyncNumberThis"));scores[round]=actual;Check(actual==expected&&(round==2||actual>0),"result equals original score function: "+actual);var e=mod.Progress.Get(mod.Song.Id,mod.Map.Id);Check(e!=null&&e.Last.Sync==actual,"score saved against song-chart pair");int plays=e.Plays;info.GetType().GetMethod("UpdateSync",All).Invoke(info,new object[]{combo});Check(Convert.ToInt32(GameChartMod.Property(info,"SyncNumberThis"))==actual&&e.Plays==plays,"repeated settlement preserves score and does not duplicate record");Check(Convert.ToInt32(GameChartMod.Property(GameChartMod.Field(info,"saveInfo"),"SyncNumber"))==originalScore,"original Candleman save unmodified");Check(Convert.ToInt32(GameChartMod.Property(info,"SyncNumber"))==e.Best.Sync,"official best score reads custom record");Check(round==2||mod.HitCount>0,"accepted tap/hold triggers sound");if(capture!=null)StartCoroutine(Capture(capture+"-result-"+round+".png"));var result=UnityEngine.Object.FindObjectOfType(game.GetType("NewSettlementController"))??UnityEngine.Object.FindObjectOfType(game.GetType("SettlementController"));Call(result,"BackToSelectSong");Next(4);}}
 if(phase==4&&scene.Contains("SelectSong")&&now-at>2){round++;if(round<3)Begin();else{Check(mod.Progress.Entries.Count>=3,"different songs/maps retain independent scores");var re=new ProgressStore(Path.Combine(root,"CustomCharts/scores.json"),MiniJSON.jsonDecode,MiniJSON.jsonEncode);re.Load();Check(re.Entries.Count==mod.Progress.Entries.Count&&re.HitSound==2,"scores and sound preferences survive reload");mod.OpenPanel();if(smallRun)typeof(GameChartMod).GetField("scoreDetails",All).SetValue(mod,true);if(capture!=null)StartCoroutine(Capture(capture+"-library.png"));Next(5);}}
 if(phase==5&&now-at>3){Log("PASS scenario features");File.WriteAllText(Path.Combine(root,"CustomCharts/smoke-features.json"),MiniJSON.jsonEncode(new Hashtable{{"status","PASS"},{"scores",scores}}));Application.Quit();}
 }catch(Exception e){Log("FAIL "+e);File.WriteAllText(Path.Combine(root,"CustomCharts/smoke-features.json"),e.ToString());Application.Quit();}}
 void Begin(){Memory("DisplayAdjustment",0);Memory("JudgeCompensate",0);var s=mod.Library.Songs[round==2?1:0];mod.Select(s,s.Charts[round==0?1:0],true);mod.SetHitSound(round==0?1:2,.35f);game.GetType("AdvSettingScript").GetField("ChooseSceneInt",All).SetValue(null,round==1?1:0);game.GetType("AdvSettingScript").GetField("unForcedUseScene",All).SetValue(null,false);mod.StartSelected();Next(1);}
 void HitNotes(){long ticks=Convert.ToInt64(GameChartMod.Property(mod.Player,"PlayTicks"));foreach(IEnumerable lane in (IEnumerable)GameChartMod.Field(mod.Player,"noteByTrack"))foreach(var sheath in lane){var entity=GameChartMod.Field(sheath,"noteEntity");if(entity==null||!(entity.GetType().Name=="Note"||entity.GetType().Name=="LongNote")||Convert.ToBoolean(GameChartMod.Property(entity,"Knocked")))continue;long insert=Convert.ToInt64(GameChartMod.Property(entity,"InsertTime"));if(ticks>=insert&&ticks-insert<800000){Set(mod.Player,"PlayTicks",insert);mod.Player.GetType().GetMethod("AddButton",All).Invoke(mod.Player,new[]{GameChartMod.Property(entity,"Track")});Set(mod.Player,"PlayTicks",ticks);}}
 }
 IEnumerator Capture(string file){yield return new WaitForEndOfFrame();var t=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,Screen.width,Screen.height),0,0);t.Apply();File.WriteAllBytes(file,t.EncodeToPNG());Destroy(t);Log("captured "+file);}
}
